import{z as B,x as A,o as n,c as p,q as l,j as o,D as t,d as s,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"二叉查找树","description":"","frontmatter":{"title":"二叉查找树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bst.md","filePath":"cs/bst.md","lastUpdated":1791063341000}'),d={name:"cs/bst.md"};function h(m,a,T,c,u,f){const r=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=l('<h1 id="二叉查找树" tabindex="-1">二叉查找树 <a class="header-anchor" href="#二叉查找树" aria-label="Permalink to &quot;二叉查找树&quot;">​</a></h1><div class="epigraph"><p>左子树都小于根、右子树都大于根，查找就沿着一条根到叶的路径走，步数等于高度。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Knuth, TAOCP 卷 3 整理</footer></div><p><a href="/cs/amortized-analysis">上一课</a>让动态数组的端操作摊还 \\(\\Theta(1)\\)。按下标已经解决；按键查找在无序数组或链表上仍是 \\(\\Theta(n)\\)。<a href="/cs/tree-as-acyclic">树作为无环连通图</a>已经有树。<a href="/cs/asymptotic-notation">渐近记号</a>把高度写成 \\(h\\)。本课不重讲摊还。缺口是有序字典的第一种树表示：二叉查找树（BST）不变式，查找/插入沿比较路径。平衡不在本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组有序可用二分，但插入要搬移。链表插入廉价，不能二分。缺口是：节点带左右孩子，<strong>中序遍历恰好是键的排序</strong>，从而比较一次丢掉一边。合同：查找、插入、删除与后继。</p><p>没有平衡时，\\(h\\) 最坏 \\(n\\)（插成链），最坏查找 \\(\\Theta(n)\\)，退回链表。本课必须把这个边界说清，否则后课 AVL 没有动机。</p><p><span class="marginnote">随机插入下期望高度 \\(O(\\log n)\\)，那是期望分析，不是最坏合同。本课最坏按 \\(h\\) 写。</span></p><p><span class="marginnote">不变式（invariant）翻译过来就是「任何时刻都必须成立的规矩」。BST 的规矩只有一句：任何节点，左边全小、右边全大。正因整棵树都守这条规矩，在根上比较一次才能放心丢掉整整一边——丢错边就再也找不到键了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点：键、可选卫星数据、左、右、可选父。不变式：左子树键 $\\lt $ 根 $\\lt $ 右子树键（或非严格，须统一）。查找：从根比较，小走左、大走右，空则失败。插入：失败路径的空位挂新叶。</p>',10)),(n(),o(E,null,{default:t(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%22%5D%20--%3E%20L%5B%22%E5%B7%A6%EF%BC%9A%E7%9A%86%E5%B0%8F%E4%BA%8E%E6%A0%B9%22%5D%0A%20%20R%20--%3E%20RI%5B%22%E5%8F%B3%EF%BC%9A%E7%9A%86%E5%A4%A7%E4%BA%8E%E6%A0%B9%22%5D%0A%20%20L%20--%3E%20LL%5B%22%E7%BB%A7%E7%BB%AD%20BST%22%5D%0A%20%20RI%20--%3E%20RR%5B%22%E7%BB%A7%E7%BB%AD%20BST%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"删除分三支：叶、单子、双子（用后继顶替）。本课承认双子删除要找后继，不把所有旋转请进来。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"中序遍历在 \\(\\Theta(n)\\) 内输出有序列，这是链表扫不到的「有序」加树结构。字典操作复杂度 \\(\\Theta(h)\\)，不是 \\(\\Theta(\\log n)\\)，除非另证 \\(h\\)。后课旋转保持不变式同时降 \\(h\\)。",-1)),a[6]||(a[6]=e("p",null,"下图回答一个具体问题：在一棵具体的 BST 里查 6，比较如何一次次丢掉整棵子树。",-1)),(n(),o(E,null,{default:t(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N8%5B%22%E6%AF%94%E8%BE%83%E6%A0%B9%208%EF%BC%9A6%20%E5%B0%8F%E4%BA%8E%208%22%5D%20--%3E%7C%22%E8%B5%B0%E5%B7%A6%22%7C%20N3%5B%22%E6%AF%94%E8%BE%83%203%EF%BC%9A6%20%E5%A4%A7%E4%BA%8E%203%22%5D%0A%20%20N8%20-.-%3E%7C%2210%20%E5%AD%90%E6%A0%91%E6%95%B4%E6%A3%B5%E4%B8%A2%E5%BC%83%22%7C%20DROP%5B%22%E4%B8%8D%E5%86%8D%E8%AE%BF%E9%97%AE%22%5D%0A%20%20N3%20--%3E%7C%22%E8%B5%B0%E5%8F%B3%22%7C%20N6%5B%22%E5%91%BD%E4%B8%AD%206%EF%BC%9A%E5%85%B1%203%20%E6%AC%A1%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：键 8, 3, 10, 1, 6, 14 的 BST 查 6 用 3 次比较，查 14 也只要 3 次（8 右转、10 右转、命中）；同一批键若插成链，查 14 要扫 6 个节点。\\(n=10^6\\) 时差距约是 20 次比较对 100 万次——前提是树平衡。</span></p><p>与<a href="/cs/locality-principle">局部性原理</a>：指针树同样追逐；节点池或 B 树才会把比较装进 cache 行。本课先保证正确性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入红黑位、不引入 AVL 平衡因子。也不把 BST 当成优先队列——无序堆更适合「只要最小」。重复键、卫星数据的相等策略须事先约定。</p><p>后课默认：有序字典可以放在 BST 里，代价随高度。高度无保证时，必须平衡。</p><p><span class="marginnote">常见误区：初学者以为 BST 的 \\(\\Theta(\\log n)\\) 是结构自带的保证。教材实际写的是 \\(\\Theta(h)\\)：只有树碰巧平衡时 \\(h\\) 才是 \\(\\log n\\)；按 1, 2, 3, … 顺序插入会得到一条链，查找退化成链表扫描，这正是下一课 AVL 旋转要解决的问题。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BST 不变式让比较丢掉一边；步数是高度 \\(h\\)。</li><li>最坏 \\(h=\\Theta(n)\\)；期望随机插入才对数。</li><li>旋转维持不变式并降高，是下一课 AVL。</li><li>出处：Cormen et al. 第 12 章；Knuth, <em>TAOCP</em> 卷 3。</li></ul>',8))])}const _=B(d,[["render",h]]);export{D as __pageData,_ as default};
